Author:     welpy-cw <h.w.forms@arcor.de>
AuthorDate: Thu Mar 5 17:04:58 2026 -0500
Commit:     welpy-cw <h.w.forms@arcor.de>
CommitDate: Thu Mar 5 17:04:58 2026 -0500

    Bug 2020627 - Fix POP3 state deadlock and false-success on unexpected connection drops. r=mkmelin


    If a POP3 connection dropped unexpectedly during a multi-line response (like
    UIDL), `_onClose` defaulted to `_actionDone(Cr.NS_OK)`. This caused Thunderbird
    to silently accept the failed sync as successful. Furthermore, the `LineReader`
    and NOOP states were not cleared, blinding the JS state machine to all future
    server responses, deadlocking the account until TB was restarted.

    Differential Revision: https://phabricator.services.mozilla.com/D286057

diff --git a/mailnews/local/src/Pop3Client.sys.mjs b/mailnews/local/src/Pop3Client.sys.mjs
index ec291047419..e1896c37dc0 100644
--- a/mailnews/local/src/Pop3Client.sys.mjs
+++ b/mailnews/local/src/Pop3Client.sys.mjs
@@ -65,7 +65,6 @@ export class Pop3Client {
     this._server = server.QueryInterface(Ci.nsIMsgIncomingServer);
     this._server.wrappedJSObject.runningClient = this;
     this._authenticator = new Pop3Authenticator(server);
-    this._lineReader = new LineReader();
     this._noopRespPending = false;

     // Somehow, Services.io.newURI("pop3://localhost") doesn't work, what we
@@ -143,6 +142,12 @@ export class Pop3Client {
       .QueryInterface(Ci.nsIMsgMailNewsUrl)
       .SetUrlState(true, Cr.NS_OK);
     this._server.serverBusy = true;
+
+    // Instantiate a fresh LineReader and reset NOOP state to guarantee no
+    // pollution from previous dropped connections.
+    this._lineReader = new LineReader();
+    this._noopRespPending = false;
+
     this._secureTransport = this._server.socketType == Ci.nsMsgSocketType.SSL;
     this._socket = new TCPSocket(hostname, this._server.port, {
       binaryType: "arraybuffer",
@@ -461,7 +466,13 @@ export class Pop3Client {
     if (this._authenticating) {
       // In some cases, socket is closed for invalid username/password.
       this._actionAuthResponse({ success: false });
+    } else if (!this._done) {
+      this._logger.warn(
+        "The connection closed unexpectedly while a command was active."
+      );
+      this._actionDone(Cr.NS_ERROR_NET_INTERRUPT);
     } else {
+      // Connection closed cleanly after QUIT.
       this._actionDone();
     }
   };
diff --git a/mailnews/local/test/unit/test_pop3StateDeadlock.js b/mailnews/local/test/unit/test_pop3StateDeadlock.js
new file mode 100644
index 00000000000..19c7a8aa47c
--- /dev/null
+++ b/mailnews/local/test/unit/test_pop3StateDeadlock.js
@@ -0,0 +1,115 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+/**
+ * Tests the recovery of the POP3 client after an unexpected server disconnect.
+ * Verifies that an abruptly dropped connection during a multi-line response
+ * (like UIDL) properly propagates an error, releases the server lock, and
+ * resets internal buffer states to prevent a permanent account deadlock on
+ * subsequent sync attempts.
+ */
+
+var { PromiseTestUtils } = ChromeUtils.importESModule(
+  "resource://testing-common/mailnews/PromiseTestUtils.sys.mjs"
+);
+
+var server;
+var daemon;
+var incomingServer;
+
+add_setup(async function () {
+  // Set up the POP3 daemon and server
+  [daemon, server] = setupServerDaemon();
+
+  // Override the UIDL command handler to simulate a dirty disconnect.
+  const originalUIDL = POP3_RFC5034_handler.prototype.UIDL;
+
+  let firstTime = true;
+  POP3_RFC5034_handler.prototype.UIDL = function (args) {
+    if (firstTime) {
+      firstTime = false;
+
+      // Tell the test server to cleanly drop the TCP socket
+      // immediately after sending the string returned below.
+      this.closing = true;
+
+      // Return a partial multi-line response, omitting the terminating ".\r\n"
+      return "+OK UIDL listing follows\r\n1 uniqueid001\r\n";
+    }
+    // On subsequent calls (the recovery attempt), behave normally
+    return originalUIDL.call(this, args);
+  };
+
+  server.start();
+
+  registerCleanupFunction(() => {
+    if (server) {
+      server.stop();
+    }
+    server = null;
+    daemon = null;
+    incomingServer = null;
+
+    // Clear the event loop to prevent socket leakage
+    const thread = Services.tm.currentThread;
+    while (thread.hasPendingEvents()) {
+      thread.processNextEvent(true);
+    }
+  });
+
+  // Set up the local folders and server configuration
+  incomingServer = createPop3ServerAndLocalFolders(server.port);
+  daemon.setMessages(["message1.eml"]);
+});
+
+add_task(async function test_dirty_disconnect_recovery() {
+  const urlListener = new PromiseTestUtils.PromiseUrlListener();
+
+  // Attempt 1: This will fail because our mocked server drops the connection mid-UIDL
+  MailServices.pop3.GetNewMail(
+    null,
+    urlListener,
+    localAccountUtils.inboxFolder,
+    incomingServer
+  );
+
+  server.performTest();
+
+  // Wait for the failure to propagate
+  await Assert.rejects(
+    urlListener.promise,
+    () => true,
+    "Check that getting mail properly fails due to the forced dirty disconnect"
+  );
+
+  // The server lock must be released.
+  Assert.equal(
+    incomingServer.serverBusy,
+    false,
+    "incomingServer.serverBusy should be false after the connection drops."
+  );
+
+  // Attempt 2: Ensure the internal state of the client isn't permanently polluted.
+  server.resetTest();
+  const urlListener2 = new PromiseTestUtils.PromiseUrlListener();
+
+  MailServices.pop3.GetNewMail(
+    null,
+    urlListener2,
+    localAccountUtils.inboxFolder,
+    incomingServer
+  );
+
+  server.performTest();
+
+  try {
+    await urlListener2.promise;
+    Assert.ok(
+      true,
+      "Successfully recovered and fetched mail on the second attempt."
+    );
+  } catch (e) {
+    Assert.fail(`State deadlock detected! Client failed to recover: ${e}`);
+  }
+});
